"use client";

import {
  AlertCircle, AlertTriangle, ArrowUpRight, Ban, BellRing, CalendarCheck, CalendarClock,
  CalendarDays, Camera, Check, CheckCircle2, ChevronRight, CircleDollarSign, ClipboardList, Clock3,
  Eye, FileDown, LayoutDashboard, Loader2, LogOut, MapPin, MapPinned, Menu, MessageCircle, Pencil,
  PlayCircle, Plus, ReceiptText, RefreshCw, RotateCcw, Save, Search, Settings2, ShieldCheck, Sparkles,
  Trash2, TrendingUp, UserPlus, UsersRound, WalletCards, Wrench, X,
} from "lucide-react";
import { FormEvent, useCallback, useEffect, useMemo, useState } from "react";
import { dateTime, money, shortDate, todayIso, whatsappLink } from "../lib/format";
import { deliverOrderPdf } from "../lib/order-pdf";
import { supabase } from "../lib/supabase";
import type { Client, FollowUp, Order, Payment, Profile, Receivable, ReturnPreset, Service, ServiceOption, YanSettings } from "../lib/types";
import { serviceAgeLabel } from "../lib/workflow";
import { ClientDialog, CompleteDialog, EditClientDialog, EditServiceDialog, OptionDialog, OrderDialog, PaymentDialog, RefundDialog, ServiceDialog, StartDialog } from "./dialogs";

type Tab = "dashboard" | "leads" | "agenda" | "clients" | "finance" | "services" | "settings";
type Settings = YanSettings;

const nav: { id: Tab; label: string; icon: typeof LayoutDashboard }[] = [
  { id: "dashboard", label: "Visão geral", icon: LayoutDashboard }, { id: "leads", label: "Retornos", icon: BellRing },
  { id: "agenda", label: "Agenda e ordens", icon: CalendarDays }, { id: "clients", label: "Clientes", icon: UsersRound },
  { id: "finance", label: "Financeiro", icon: WalletCards }, { id: "services", label: "Serviços", icon: Wrench },
  { id: "settings", label: "Configurações", icon: Settings2 },
];

export function Management({ profile }: { profile: Profile }) {
  const [tab, setTab] = useState<Tab>("dashboard"); const [menuOpen, setMenuOpen] = useState(false);
  const [clients, setClients] = useState<Client[]>([]); const [services, setServices] = useState<Service[]>([]); const [orders, setOrders] = useState<Order[]>([]);
  const [receivables, setReceivables] = useState<Receivable[]>([]); const [payments, setPayments] = useState<Payment[]>([]); const [followUps, setFollowUps] = useState<FollowUp[]>([]); const [profiles, setProfiles] = useState<Profile[]>([]); const [settings, setSettings] = useState<Settings | null>(null); const [returnPresets, setReturnPresets] = useState<ReturnPreset[]>([]);
  const [loading, setLoading] = useState(true); const [refreshing, setRefreshing] = useState(false); const [loadError, setLoadError] = useState(""); const [toast, setToast] = useState("");
  const [clientDialog, setClientDialog] = useState(false); const [editingClient, setEditingClient] = useState<Client | null>(null); const [orderClientId, setOrderClientId] = useState<string | null | undefined>(undefined); const [startOrder, setStartOrder] = useState<Order | null>(null); const [completeOrder, setCompleteOrder] = useState<Order | null>(null); const [paymentTarget, setPaymentTarget] = useState<Receivable | null>(null); const [refundTarget, setRefundTarget] = useState<Order | null>(null); const [serviceDialog, setServiceDialog] = useState(false); const [editingService, setEditingService] = useState<Service | null>(null); const [optionService, setOptionService] = useState<Service | null>(null);

  const notify = useCallback((message: string) => { setToast(message); window.setTimeout(() => setToast(""), 3600); }, []);
  const loadAll = useCallback(async (quiet = false) => {
    if (quiet) setRefreshing(true); else setLoading(true);
    setLoadError("");
    const results = await Promise.all([
      supabase.from("yan_services").select("*").order("sort_order").order("name"),
      supabase.from("yan_service_options").select("*").order("sort_order").order("name"),
      supabase.from("yan_return_presets").select("*").order("sort_order").order("value"),
      supabase.from("yan_clients").select("*").order("created_at", { ascending: false }),
      supabase.from("yan_orders").select("*, client:yan_clients(*), items:yan_order_items(*, service:yan_services(id,name), option:yan_service_options(id,name)), photos:yan_order_photos(*)").order("created_at", { ascending: false }),
      supabase.from("yan_receivables").select("*, order:yan_orders(order_number, client:yan_clients(name,whatsapp))").order("due_date"),
      supabase.from("yan_payments").select("*").order("occurred_at", { ascending: false }),
      supabase.from("yan_follow_ups").select("*, client:yan_clients(*), service:yan_services(name)").order("due_date"),
      supabase.from("yan_profiles").select("user_id,email,full_name,role,active").order("created_at"),
      supabase.from("yan_settings").select("*").eq("id", "main").maybeSingle(),
    ]);
    const firstError = results.find((result) => result.error)?.error;
    if (firstError) setLoadError(firstError.message);
    const [serviceResult, optionResult, presetResult, clientResult, orderResult, receivableResult, paymentResult, followResult, profileResult, settingResult] = results;
    const optionRows = (optionResult.data ?? []) as ServiceOption[];
    setServices(((serviceResult.data ?? []) as Service[]).map((service) => ({ ...service, options: optionRows.filter((option) => option.service_id === service.id) })));
    setReturnPresets((presetResult.data ?? []) as ReturnPreset[]); setClients((clientResult.data ?? []) as Client[]); setOrders((orderResult.data ?? []) as unknown as Order[]); setReceivables((receivableResult.data ?? []) as unknown as Receivable[]);
    setPayments((paymentResult.data ?? []) as Payment[]); setFollowUps((followResult.data ?? []) as unknown as FollowUp[]); setProfiles((profileResult.data ?? []) as Profile[]); setSettings(settingResult.data as Settings | null);
    setLoading(false); setRefreshing(false);
  }, []);

  useEffect(() => {
    const timer = window.setTimeout(() => { void loadAll(); }, 0);
    return () => window.clearTimeout(timer);
  }, [loadAll]);

  function openTab(next: Tab) { setTab(next); setMenuOpen(false); }
  function openOrder(clientId?: string) { setOrderClientId(clientId ?? null); }
  async function refreshed(message?: string) { await loadAll(true); if (message) notify(message); }
  const refundAvailable = refundTarget ? payments.filter((payment) => payment.order_id === refundTarget.id).reduce((sum, payment) => sum + (payment.kind === "payment" ? Number(payment.amount) : -Number(payment.amount)), 0) : 0;

  return <main className="management-shell">
    <aside className={menuOpen ? "management-sidebar open" : "management-sidebar"}>
      <div className="sidebar-brand"><img src="/yan-logo.jpeg" alt="Yan" /><span><strong>YAN</strong><small>Gestão de serviços</small></span><button onClick={() => setMenuOpen(false)}><X /></button></div>
      <nav>{nav.map(({ id, label, icon: Icon }) => <button key={id} onClick={() => openTab(id)} className={tab === id ? "active" : ""}><Icon /><span>{label}</span>{id === "leads" && followUps.filter((entry) => ["pending", "contacted", "snoozed"].includes(entry.status) && entry.due_date <= todayIso()).length > 0 && <b>{followUps.filter((entry) => ["pending", "contacted", "snoozed"].includes(entry.status) && entry.due_date <= todayIso()).length}</b>}</button>)}</nav>
      <div className="sidebar-profile"><div>{(profile.full_name ?? profile.email).slice(0, 1).toUpperCase()}</div><span><strong>{profile.full_name ?? "Equipe Yan"}</strong><small>{profile.role === "admin" ? "Administrador" : "Atendente"}</small></span><button onClick={() => void supabase.auth.signOut()} title="Sair"><LogOut /></button></div>
    </aside>
    {menuOpen && <div className="sidebar-scrim" onClick={() => setMenuOpen(false)} />}
    <section className="management-main">
      <header className="management-topbar"><button className="mobile-menu" onClick={() => setMenuOpen(true)}><Menu /></button><div><small>Yan Limpeza</small><strong>{nav.find((item) => item.id === tab)?.label}</strong></div><div className="topbar-actions"><button className="icon-button" onClick={() => void loadAll(true)} title="Atualizar"><RefreshCw className={refreshing ? "spin" : ""} /></button><button className="quick-order" onClick={() => openOrder()}><Plus /> Nova ordem</button></div></header>
      <div className="management-content">
        {loadError && <div className="form-alert error"><AlertTriangle />{loadError}<button onClick={() => void loadAll()}>Tentar novamente</button></div>}
        {loading ? <ContentLoader /> : <>
          {tab === "dashboard" && <Dashboard orders={orders} payments={payments} receivables={receivables} followUps={followUps} clients={clients} onOpenTab={openTab} onNewOrder={openOrder} />}
          {tab === "leads" && <Leads clients={clients} followUps={followUps} onNewClient={() => setClientDialog(true)} onBook={openOrder} onRefresh={() => refreshed("Retorno atualizado.")} />}
          {tab === "agenda" && <OrdersView orders={orders} payments={payments} settings={settings} onNewOrder={() => openOrder()} onStart={setStartOrder} onComplete={setCompleteOrder} onRefund={setRefundTarget} onRefresh={() => refreshed()} notify={notify} />}
          {tab === "clients" && <ClientsView clients={clients} orders={orders} onNewClient={() => setClientDialog(true)} onEdit={setEditingClient} onBook={openOrder} />}
          {tab === "finance" && <FinanceView receivables={receivables} payments={payments} onReceive={setPaymentTarget} />}
          {tab === "services" && <ServicesView services={services} presets={returnPresets} isAdmin={profile.role === "admin"} onAddService={() => setServiceDialog(true)} onEditService={setEditingService} onAddOption={setOptionService} onRefresh={() => refreshed("Catálogo atualizado.")} notify={notify} />}
          {tab === "settings" && <SettingsView profile={profile} profiles={profiles} settings={settings} presets={returnPresets} onRefresh={() => refreshed("Configurações salvas.")} notify={notify} />}
        </>}
      </div>
      <nav className="mobile-bottom-nav">{nav.slice(0, 5).map(({ id, label, icon: Icon }) => <button key={id} onClick={() => openTab(id)} className={tab === id ? "active" : ""}><Icon /><span>{label === "Visão geral" ? "Início" : label === "Agenda e ordens" ? "Agenda" : label}</span></button>)}</nav>
    </section>
    {toast && <div className="toast"><CheckCircle2 />{toast}</div>}
    {clientDialog && <ClientDialog services={services} onClose={() => setClientDialog(false)} onSaved={() => refreshed("Cliente cadastrado.")} />}
    {editingClient && <EditClientDialog client={editingClient} onClose={() => setEditingClient(null)} onSaved={() => refreshed("Cliente atualizado.")} />}
    {orderClientId !== undefined && <OrderDialog clients={clients} services={services} presets={returnPresets} defaultClientId={orderClientId ?? undefined} onClose={() => setOrderClientId(undefined)} onSaved={() => refreshed("Ordem criada e agendada com sucesso.")} />}
    {startOrder && <StartDialog order={startOrder} onClose={() => setStartOrder(null)} onSaved={() => refreshed("Serviço iniciado.")} />}
    {completeOrder && <CompleteDialog order={completeOrder} settings={settings} onClose={() => setCompleteOrder(null)} onSaved={() => refreshed("Serviço concluído e financeiro atualizado.")} />}
    {paymentTarget && <PaymentDialog receivable={paymentTarget} onClose={() => setPaymentTarget(null)} onSaved={() => refreshed("Recebimento registrado.")} />}
    {refundTarget && refundAvailable > 0 && <RefundDialog order={refundTarget} available={refundAvailable} onClose={() => setRefundTarget(null)} onSaved={() => refreshed("Estorno registrado.")} />}
    {serviceDialog && <ServiceDialog presets={returnPresets} onClose={() => setServiceDialog(false)} onSaved={() => refreshed("Serviço criado.")} />}
    {editingService && <EditServiceDialog service={editingService} presets={returnPresets} onClose={() => setEditingService(null)} onSaved={() => refreshed("Serviço atualizado.")} />}
    {optionService && <OptionDialog service={optionService} presets={returnPresets} onClose={() => setOptionService(null)} onSaved={() => refreshed("Modelo adicionado.")} />}
  </main>;
}

function ContentLoader() { return <div className="content-loader"><Loader2 className="spin" /><strong>Organizando as informações...</strong><span>Clientes, agenda e financeiro</span></div>; }

type RangeKey = "today" | "yesterday" | "7d" | "30d" | "all" | "custom";
function Dashboard({ orders, payments, receivables, followUps, clients, onOpenTab, onNewOrder }: { orders: Order[]; payments: Payment[]; receivables: Receivable[]; followUps: FollowUp[]; clients: Client[]; onOpenTab: (tab: Tab) => void; onNewOrder: (id?: string) => void }) {
  const [range, setRange] = useState<RangeKey>("30d"); const [customStart, setCustomStart] = useState(todayIso()); const [customEnd, setCustomEnd] = useState(todayIso());
  const bounds = useMemo(() => {
    const today = new Date(`${todayIso()}T00:00:00`); let start: Date | null = null; let end: Date | null = new Date(today.getTime() + 86_400_000);
    if (range === "today") start = today;
    if (range === "yesterday") { start = new Date(today.getTime() - 86_400_000); end = today; }
    if (range === "7d") start = new Date(today.getTime() - 6 * 86_400_000);
    if (range === "30d") start = new Date(today.getTime() - 29 * 86_400_000);
    if (range === "all") { start = null; end = null; }
    if (range === "custom") { start = new Date(`${customStart}T00:00:00`); end = new Date(new Date(`${customEnd}T00:00:00`).getTime() + 86_400_000); }
    return { start, end };
  }, [customEnd, customStart, range]);
  const includes = useCallback((value: string | null) => { if (!value) return false; const date = new Date(value); return (!bounds.start || date >= bounds.start) && (!bounds.end || date < bounds.end); }, [bounds]);
  const billedOrders = orders.filter((order) => order.status === "completed" && includes(order.completed_at));
  const billed = billedOrders.reduce((sum, order) => sum + Number(order.total), 0); const cost = billedOrders.reduce((sum, order) => sum + Number(order.cost_total), 0);
  const cash = payments.filter((payment) => includes(payment.occurred_at)).reduce((sum, payment) => sum + (payment.kind === "payment" ? Number(payment.amount) : -Number(payment.amount)), 0);
  const openBalance = receivables.filter((entry) => ["pending", "partial"].includes(entry.status)).reduce((sum, entry) => sum + Number(entry.balance), 0);
  const today = todayIso(); const endWeek = new Date(`${today}T12:00:00`); endWeek.setDate(endWeek.getDate() + 7); const weekIso = endWeek.toISOString().slice(0, 10);
  const todayOrders = orders.filter((order) => order.scheduled_start?.slice(0, 10) === today && ["scheduled", "in_progress"].includes(order.status)).sort((a, b) => (a.scheduled_start ?? "").localeCompare(b.scheduled_start ?? ""));
  const weekOrders = orders.filter((order) => order.scheduled_start && order.scheduled_start.slice(0, 10) >= today && order.scheduled_start.slice(0, 10) < weekIso && ["scheduled", "in_progress"].includes(order.status));
  const overdue = followUps.filter((entry) => ["pending", "contacted", "snoozed"].includes(entry.status) && entry.due_date <= today);
  const topServices = Object.entries(billedOrders.flatMap((order) => order.items ?? []).reduce<Record<string, number>>((acc, item) => { const name = item.service?.name ?? item.description.split(" · ")[0]; acc[name] = (acc[name] ?? 0) + 1; return acc; }, {})).sort((a, b) => b[1] - a[1]);
  const neighborhoods = Object.entries(orders.filter((order) => order.status === "completed" && order.neighborhood).reduce<Record<string, number>>((acc, order) => { const name = order.neighborhood as string; acc[name] = (acc[name] ?? 0) + 1; return acc; }, {})).sort((a, b) => b[1] - a[1]).slice(0, 8);
  const maxNeighborhood = Math.max(1, ...neighborhoods.map(([, value]) => value));

  return <div className="dashboard-view">
    <section className="dashboard-welcome"><div><span className="page-kicker"><Sparkles /> Painel de controle</span><h1>Bom trabalho, equipe Yan.</h1><p>Agenda, retornos e dinheiro organizados em uma única visão.</p></div><button className="button-admin-primary" onClick={() => onNewOrder()}><Plus /> Abrir nova ordem</button></section>
    <section className="period-bar"><strong>Período</strong><div>{(["today", "yesterday", "7d", "30d", "all"] as RangeKey[]).map((key) => <button key={key} className={range === key ? "active" : ""} onClick={() => setRange(key)}>{{ today: "Hoje", yesterday: "Ontem", "7d": "7 dias", "30d": "30 dias", all: "Geral" }[key]}</button>)}<button className={range === "custom" ? "active" : ""} onClick={() => setRange("custom")}><CalendarDays /> Personalizar</button></div>{range === "custom" && <div className="custom-dates"><input type="date" value={customStart} onChange={(e) => setCustomStart(e.target.value)} /><span>até</span><input type="date" value={customEnd} onChange={(e) => setCustomEnd(e.target.value)} /></div>}</section>
    <section className="metric-grid">
      <Metric icon={TrendingUp} tone="blue" label="Serviços concluídos" value={money(billed)} detail={`${billedOrders.length} ordens no período`} trend={billed - cost} trendLabel="margem bruta" />
      <Metric icon={CircleDollarSign} tone="green" label="Dinheiro recebido" value={money(cash)} detail="pagamentos menos estornos" />
      <Metric icon={ReceiptText} tone="amber" label="A receber" value={money(openBalance)} detail={`${receivables.filter((entry) => ["pending", "partial"].includes(entry.status)).length} parcelas abertas`} />
      <Metric icon={CalendarCheck} tone="purple" label="Agenda da semana" value={`${weekOrders.length}`} detail={`${todayOrders.length} atendimento(s) hoje`} />
    </section>
    {overdue.length > 0 && <section className="attention-banner"><div><span><BellRing /></span><div><strong>{overdue.length} cliente{overdue.length > 1 ? "s precisam" : " precisa"} de atenção</strong><p>Há retornos vencidos ou previstos para hoje. Este é o momento de chamar no WhatsApp.</p></div></div><button onClick={() => onOpenTab("leads")}>Ver retornos <ChevronRight /></button></section>}
    <div className="dashboard-columns">
      <section className="panel"><PanelHead icon={Clock3} title="Atendimentos de hoje" subtitle={todayOrders.length ? "Sua rota para hoje" : "Agenda livre por enquanto"} action={<button onClick={() => onOpenTab("agenda")}>Ver agenda</button>} />
        <div className="today-timeline">{todayOrders.length ? todayOrders.map((order) => <article key={order.id}><time>{order.scheduled_start ? new Intl.DateTimeFormat("pt-BR", { hour: "2-digit", minute: "2-digit" }).format(new Date(order.scheduled_start)) : "—"}</time><span className={order.status === "in_progress" ? "timeline-dot active" : "timeline-dot"} /><div><strong>{order.client?.name}</strong><p>{order.items?.map((item) => item.service?.name).filter(Boolean).join(", ") || "Serviço"}</p><small><MapPin /> {order.neighborhood || "Endereço a confirmar"}</small></div><a href={whatsappLink(order.client?.whatsapp ?? "", `Olá, ${order.client?.name?.split(" ")[0] ?? ""}! Confirmando seu atendimento com a Yan Limpeza.`)} target="_blank" rel="noreferrer"><MessageCircle /></a></article>) : <Empty icon={CalendarCheck} title="Nenhum serviço marcado hoje" text="Aproveite para organizar retornos ou abrir uma nova ordem." action={<button onClick={() => onNewOrder()}><Plus /> Nova ordem</button>} />}</div>
      </section>
      <section className="panel"><PanelHead icon={TrendingUp} title="Serviços mais realizados" subtitle="No período selecionado" />{topServices.length ? <div className="ranking-list">{topServices.slice(0, 5).map(([name, count], index) => <div key={name}><span>{index + 1}</span><strong>{name}</strong><div><i style={{ width: `${Math.max(14, count / topServices[0][1] * 100)}%` }} /></div><b>{count}</b></div>)}</div> : <Empty icon={ClipboardList} title="Sem serviços concluídos" text="O ranking aparecerá conforme as ordens forem encerradas." />}</section>
    </div>
    <div className="dashboard-columns map-columns"><section className="panel neighborhood-panel"><PanelHead icon={MapPinned} title="Mapa comercial de bairros" subtitle="Onde estão seus clientes atendidos" />{neighborhoods.length ? <div className="neighborhood-map"><div className="map-grid" />{neighborhoods.map(([name, count], index) => <div key={name} className={`map-bubble bubble-${index + 1}`} style={{ "--bubble": `${54 + count / maxNeighborhood * 54}px` } as React.CSSProperties}><strong>{count}</strong><span>{name}</span></div>)}</div> : <Empty icon={MapPinned} title="O mapa está começando" text="Informe o bairro nos cadastros para descobrir onde a Yan atende mais." />}</section>
      <section className="panel"><PanelHead icon={UsersRound} title="Base de clientes" subtitle="Relacionamento em movimento" /><div className="client-summary"><div><span className="summary-icon blue"><UsersRound /></span><p><strong>{clients.length}</strong><small>clientes cadastrados</small></p></div><div><span className="summary-icon green"><CheckCircle2 /></span><p><strong>{clients.filter((client) => client.previous_customer).length}</strong><small>já atendidos</small></p></div><div><span className="summary-icon amber"><Clock3 /></span><p><strong>{clients.filter((client) => !client.previous_customer).length}</strong><small>ainda não atendidos</small></p></div></div><button className="panel-full-action" onClick={() => onOpenTab("clients")}>Explorar todos os clientes <ChevronRight /></button></section>
    </div>
  </div>;
}

function Metric({ icon: Icon, tone, label, value, detail, trend, trendLabel }: { icon: typeof TrendingUp; tone: string; label: string; value: string; detail: string; trend?: number; trendLabel?: string }) { return <article className="metric-card"><div className={`metric-icon ${tone}`}><Icon /></div><div><span>{label}</span><strong>{value}</strong><small>{detail}</small></div>{trend !== undefined && <em><ArrowUpRight />{money(trend)} {trendLabel}</em>}</article>; }
function PanelHead({ icon: Icon, title, subtitle, action }: { icon: typeof Clock3; title: string; subtitle?: string; action?: React.ReactNode }) { return <header className="panel-head"><div className="panel-title-icon"><Icon /></div><div><h2>{title}</h2>{subtitle && <p>{subtitle}</p>}</div>{action && <div className="panel-action">{action}</div>}</header>; }
function Empty({ icon: Icon, title, text, action }: { icon: typeof CalendarCheck; title: string; text: string; action?: React.ReactNode }) { return <div className="empty-state"><Icon /><strong>{title}</strong><p>{text}</p>{action}</div>; }

function Leads({ clients, followUps, onNewClient, onBook, onRefresh }: { clients: Client[]; followUps: FollowUp[]; onNewClient: () => void; onBook: (id: string) => void; onRefresh: () => Promise<void> }) {
  const [filter, setFilter] = useState<"all" | "overdue" | "decision" | "recurrence">("all"); const [snoozeId, setSnoozeId] = useState<string | null>(null); const [snoozeDate, setSnoozeDate] = useState(""); const [busy, setBusy] = useState(false);
  const today = todayIso(); const active = followUps.filter((entry) => ["pending", "contacted", "snoozed"].includes(entry.status));
  const missing = clients.filter((client) => ["pending", "not_now"].includes(client.decision_status) && !active.some((entry) => entry.client_id === client.id)).map((client) => ({ id: `client-${client.id}`, client_id: client.id, due_date: client.follow_up_at ?? today, kind: "decision", status: "pending", notes: "Atendimento aguardando decisão", client } as FollowUp));
  const rows = [...active, ...missing].filter((entry) => filter === "all" || (filter === "overdue" ? entry.due_date <= today : entry.kind === filter)).sort((a, b) => a.due_date.localeCompare(b.due_date));
  async function snooze(entry: FollowUp) { if (!snoozeDate) return; setBusy(true); await Promise.all([entry.id.startsWith("client-") ? supabase.from("yan_follow_ups").insert({ client_id: entry.client_id, due_date: snoozeDate, kind: entry.kind, status: "snoozed", notes: "Novo lembrete após contato" }) : supabase.from("yan_follow_ups").update({ due_date: snoozeDate, status: "snoozed" }).eq("id", entry.id), supabase.from("yan_clients").update({ decision_status: "not_now", follow_up_at: snoozeDate }).eq("id", entry.client_id)]); setSnoozeId(null); setSnoozeDate(""); setBusy(false); await onRefresh(); }
  return <div><PageHeader kicker="Relacionamento" title="Retornos e oportunidades" text="Clientes que aguardam decisão ou já chegaram ao período recomendado para uma nova limpeza." action={<button className="button-admin-primary" onClick={onNewClient}><UserPlus /> Novo atendimento</button>} />
    <div className="filter-chips"><button className={filter === "all" ? "active" : ""} onClick={() => setFilter("all")}>Todos <b>{active.length + missing.length}</b></button><button className={filter === "overdue" ? "active" : ""} onClick={() => setFilter("overdue")}>Vencidos / hoje</button><button className={filter === "decision" ? "active" : ""} onClick={() => setFilter("decision")}>Aguardando decisão</button><button className={filter === "recurrence" ? "active" : ""} onClick={() => setFilter("recurrence")}>Hora de refazer</button></div>
    <div className="lead-grid">{rows.map((entry) => { const client = entry.client; if (!client) return null; const overdue = entry.due_date <= today; return <article className={overdue ? "lead-card overdue" : "lead-card"} key={entry.id}><div className="lead-card-head"><span className={`lead-kind ${entry.kind}`}>{entry.kind === "recurrence" ? <RotateCcw /> : <MessageCircle />}{entry.kind === "recurrence" ? "Retorno recomendado" : "Aguardando decisão"}</span><span className={overdue ? "due overdue" : "due"}><CalendarClock />{entry.due_date === today ? "Hoje" : shortDate(entry.due_date)}</span></div><div className="lead-person"><div>{client.name.slice(0, 1).toUpperCase()}</div><span><h3>{client.name}</h3><p>{client.whatsapp}</p></span></div>{entry.kind === "recurrence" && <div className="lead-reason"><Sparkles /><span><strong>{entry.service?.name ?? client.last_service_description ?? "Higienização"}</strong><small>Último serviço: {shortDate(client.last_service_date)}</small></span></div>}<p className="lead-note">{entry.notes || (client.previous_customer ? "Cliente já atendido pela Yan." : "Cliente ainda não realizou o primeiro serviço.")}</p><div className="lead-actions"><a className="whatsapp-action" href={whatsappLink(client.whatsapp, `Olá, ${client.name.split(" ")[0]}! Tudo bem? Aqui é da Yan Limpeza. Posso te ajudar a cuidar dos seus estofados?`)} target="_blank" rel="noreferrer"><MessageCircle /> Chamar no WhatsApp</a><button onClick={() => onBook(client.id)}><Check /> Fechou serviço</button><button onClick={() => { setSnoozeId(entry.id); setSnoozeDate(""); }}><Clock3 /> Não agora</button></div>{snoozeId === entry.id && <div className="snooze-box"><label>Quando lembrar novamente?<input type="date" min={today} value={snoozeDate} onChange={(e) => setSnoozeDate(e.target.value)} /></label><button disabled={busy || !snoozeDate} onClick={() => void snooze(entry)}>{busy ? <Loader2 className="spin" /> : <Save />}Salvar lembrete</button><button onClick={() => setSnoozeId(null)}><X /></button></div>}</article>; })}</div>
    {!rows.length && <div className="panel"><Empty icon={CheckCircle2} title="Tudo em dia por aqui" text="Nenhum cliente corresponde ao filtro escolhido." /></div>}
  </div>;
}

function ClientsView({ clients, orders, onNewClient, onEdit, onBook }: { clients: Client[]; orders: Order[]; onNewClient: () => void; onEdit: (client: Client) => void; onBook: (id: string) => void }) {
  const [search, setSearch] = useState(""); const [selected, setSelected] = useState<string | null>(null); const [group, setGroup] = useState<"all" | "served" | "new">("all");
  const visible = clients.filter((client) => (group === "all" || (group === "served" ? client.previous_customer : !client.previous_customer)) && `${client.name} ${client.whatsapp} ${client.neighborhood ?? ""}`.toLowerCase().includes(search.toLowerCase()));
  const chosen = clients.find((client) => client.id === selected); const history = chosen ? orders.filter((order) => order.client_id === chosen.id) : []; const spent = history.filter((order) => order.status === "completed").reduce((sum, order) => sum + Number(order.total), 0);
  return <div><PageHeader kicker="Base de relacionamento" title="Meus clientes" text="Ficha completa, histórico, total gasto e WhatsApp sempre à mão." action={<button className="button-admin-primary" onClick={onNewClient}><UserPlus /> Cadastrar cliente</button>} /><div className="toolbar"><div className="search-box"><Search /><input value={search} onChange={(e) => setSearch(e.target.value)} placeholder="Buscar nome, telefone ou bairro" /></div><div className="segmented"><button className={group === "all" ? "active" : ""} onClick={() => setGroup("all")}>Todos</button><button className={group === "served" ? "active" : ""} onClick={() => setGroup("served")}>Já atendidos</button><button className={group === "new" ? "active" : ""} onClick={() => setGroup("new")}>Nunca atendidos</button></div></div>
    <div className="clients-layout"><div className="client-list">{visible.map((client) => { const clientOrders = orders.filter((order) => order.client_id === client.id); return <button key={client.id} className={selected === client.id ? "client-list-card selected" : "client-list-card"} onClick={() => setSelected(client.id)}><div className="avatar">{client.name.slice(0, 1).toUpperCase()}</div><div><strong>{client.name}</strong><p>{client.whatsapp}</p><small><MapPin />{client.neighborhood || "Bairro não informado"}</small><em className={client.last_service_date ? "service-age served" : "service-age"}>{serviceAgeLabel(client.last_service_date)}</em></div><span><b>{clientOrders.length}</b><small>ordens</small></span><ChevronRight /></button>; })}{!visible.length && <div className="panel"><Empty icon={UsersRound} title="Nenhum cliente encontrado" text="Tente outro termo ou cadastre um novo atendimento." /></div>}</div>
      <aside className={chosen ? "client-profile open" : "client-profile"}>{chosen ? <><div className="client-profile-hero"><div className="large-avatar">{chosen.name.slice(0, 1).toUpperCase()}</div><div><h2>{chosen.name}</h2><p>{chosen.whatsapp}</p><span className={chosen.previous_customer ? "status-pill success" : "status-pill neutral"}>{serviceAgeLabel(chosen.last_service_date)}</span></div><button className="close-profile" onClick={() => setSelected(null)}><X /></button></div><div className="profile-actions"><a href={whatsappLink(chosen.whatsapp, `Olá, ${chosen.name.split(" ")[0]}! Aqui é da Yan Limpeza.`)} target="_blank" rel="noreferrer"><MessageCircle /> WhatsApp</a><button onClick={() => onBook(chosen.id)}><Plus /> Nova ordem</button><button className="edit-client-action" onClick={() => onEdit(chosen)}><Pencil /> Editar cliente</button></div><div className="profile-metrics"><div><strong>{money(spent)}</strong><span>Total em serviços</span></div><div><strong>{history.length}</strong><span>Ordens</span></div><div><strong>{shortDate(chosen.last_service_date)}</strong><span>Último serviço</span></div></div><section className="profile-detail"><h3>Contato e endereço</h3><p><strong>E-mail</strong><span>{chosen.email || "Não informado"}</span></p><p><strong>CEP</strong><span>{chosen.zipcode || "Não informado"}</span></p><p><strong>Endereço</strong><span>{[chosen.street, chosen.street_number, chosen.complement, chosen.neighborhood, chosen.city].filter(Boolean).join(", ") || "Não informado"}</span></p>{chosen.notes && <p><strong>Observações</strong><span>{chosen.notes}</span></p>}</section><section className="profile-history"><h3>Histórico de ordens</h3>{history.length ? history.map((order) => <div key={order.id}><span className={`order-status ${order.status}`}>{statusName(order.status)}</span><div><strong>Ordem #{order.order_number}</strong><small>{order.items?.map((item) => item.service?.name).filter(Boolean).join(", ") || "Serviço"}</small></div><span><strong>{money(order.total)}</strong><small>{shortDate(order.completed_at ?? order.created_at)}</small></span></div>) : <p className="muted-empty">Nenhuma ordem registrada.</p>}</section></> : <Empty icon={Eye} title="Selecione um cliente" text="A ficha completa aparecerá aqui." />}</aside></div>
  </div>;
}

function OrdersView({ orders, payments, settings, onNewOrder, onStart, onComplete, onRefund, onRefresh, notify }: { orders: Order[]; payments: Payment[]; settings: Settings | null; onNewOrder: () => void; onStart: (order: Order) => void; onComplete: (order: Order) => void; onRefund: (order: Order) => void; onRefresh: () => Promise<void>; notify: (text: string) => void }) {
  const [filter, setFilter] = useState("active"); const [search, setSearch] = useState("");
  const visible = orders.filter((order) => (filter === "all" || (filter === "active" ? ["draft", "scheduled", "in_progress"].includes(order.status) : order.status === filter)) && `${order.order_number} ${order.client?.name ?? ""}`.toLowerCase().includes(search.toLowerCase()));
  async function cancel(order: Order) { const reason = window.prompt("Informe o motivo do cancelamento:"); if (!reason) return; const { error } = await supabase.rpc("yan_cancel_order", { p_order_id: order.id, p_reason: reason }); if (error) notify(error.message); else { notify("Ordem cancelada."); await onRefresh(); } }
  async function pdf(order: Order) { try { await deliverOrderPdf(order, settings); } catch (caught) { notify(caught instanceof Error ? caught.message : "Não foi possível gerar o PDF."); } }
  function available(order: Order) { return payments.filter((payment) => payment.order_id === order.id).reduce((sum, payment) => sum + (payment.kind === "payment" ? Number(payment.amount) : -Number(payment.amount)), 0); }
  return <div><PageHeader kicker="Operação" title="Agenda e ordens de serviço" text="Veja a rota, inicie o atendimento e encerre o serviço ainda na casa do cliente." action={<button className="button-admin-primary" onClick={onNewOrder}><Plus /> Nova ordem</button>} /><div className="toolbar"><div className="search-box"><Search /><input value={search} onChange={(e) => setSearch(e.target.value)} placeholder="Buscar ordem ou cliente" /></div><div className="filter-chips compact">{[{ id: "active", label: "Em aberto" }, { id: "scheduled", label: "Agendadas" }, { id: "completed", label: "Concluídas" }, { id: "cancelled", label: "Canceladas" }, { id: "all", label: "Todas" }].map((entry) => <button key={entry.id} className={filter === entry.id ? "active" : ""} onClick={() => setFilter(entry.id)}>{entry.label}</button>)}</div></div>
    <div className="order-list">{visible.map((order) => <article className={order.status === "completed" ? "order-card completed-card" : "order-card"} key={order.id}><div className="order-date-block"><strong>{order.scheduled_start ? new Intl.DateTimeFormat("pt-BR", { day: "2-digit" }).format(new Date(order.scheduled_start)) : "—"}</strong><span>{order.scheduled_start ? new Intl.DateTimeFormat("pt-BR", { month: "short" }).format(new Date(order.scheduled_start)) : "sem data"}</span><small>{order.scheduled_start ? new Intl.DateTimeFormat("pt-BR", { hour: "2-digit", minute: "2-digit" }).format(new Date(order.scheduled_start)) : "rascunho"}</small></div><div className="order-card-main"><header><span className={`order-status ${order.status}`}>{statusName(order.status)}</span><small>Ordem #{order.order_number}</small>{order.photos?.length ? <small className="photo-count"><Camera />{order.photos.length}</small> : null}</header><h3>{order.client?.name}</h3><p className="order-services">{order.items?.map((item) => item.description).join(" · ") || "Nenhum item"}</p><div className="order-meta"><span><MapPin />{[order.street, order.street_number, order.neighborhood].filter(Boolean).join(", ") || "Endereço não informado"}</span><span><Clock3 />{order.scheduled_start && order.scheduled_end ? `${dateTime(order.scheduled_start)} até ${new Intl.DateTimeFormat("pt-BR", { hour: "2-digit", minute: "2-digit" }).format(new Date(order.scheduled_end))}` : "Horário a definir"}</span>{order.completed_at && <span className="completed-at"><CheckCircle2 />Concluído em {dateTime(order.completed_at)}</span>}</div></div><div className="order-value"><small>Total</small><strong>{money(order.total)}</strong><span>{order.return_label ? `Retorno: ${order.return_label}` : order.discount_amount > 0 ? `${money(order.discount_amount)} de desconto` : "sem desconto"}</span></div><div className="order-actions"><a href={whatsappLink(order.client?.whatsapp ?? "", `Olá, ${order.client?.name?.split(" ")[0] ?? ""}! Falando sobre sua ordem #${order.order_number} da Yan Limpeza.`)} target="_blank" rel="noreferrer" title="WhatsApp"><MessageCircle /></a>{order.status === "scheduled" && <button onClick={() => onStart(order)} title="Iniciar"><PlayCircle /></button>}{["scheduled", "in_progress"].includes(order.status) && <button className="complete-action" onClick={() => onComplete(order)}><Check /> Concluir</button>}{["draft", "scheduled", "in_progress"].includes(order.status) && <button onClick={() => void cancel(order)} title="Cancelar"><Ban /></button>}{order.status === "completed" && <button onClick={() => void pdf(order)} title="Baixar PDF"><FileDown /></button>}{["completed", "refunded"].includes(order.status) && available(order) > 0 && <button onClick={() => onRefund(order)} title="Estornar"><RotateCcw /></button>}</div></article>)}</div>{!visible.length && <div className="panel"><Empty icon={CalendarDays} title="Nenhuma ordem encontrada" text="Altere o filtro ou abra uma nova ordem de serviço." /></div>}
  </div>;
}

function FinanceView({ receivables, payments, onReceive }: { receivables: Receivable[]; payments: Payment[]; onReceive: (entry: Receivable) => void }) {
  const [filter, setFilter] = useState<"open" | "overdue" | "paid" | "all">("open"); const today = todayIso();
  const open = receivables.filter((entry) => ["pending", "partial"].includes(entry.status)); const overdue = open.filter((entry) => entry.due_date < today); const received = payments.filter((entry) => entry.kind === "payment").reduce((sum, entry) => sum + Number(entry.amount), 0); const refunded = payments.filter((entry) => entry.kind === "refund").reduce((sum, entry) => sum + Number(entry.amount), 0);
  const visible = receivables.filter((entry) => filter === "all" || (filter === "open" ? ["pending", "partial"].includes(entry.status) : filter === "overdue" ? ["pending", "partial"].includes(entry.status) && entry.due_date < today : entry.status === "paid"));
  return <div><PageHeader kicker="Controle financeiro" title="Contas a receber" text="Receba integral ou parcialmente, reagende o saldo e acompanhe tudo que entrou." /><section className="metric-grid finance-metrics"><Metric icon={WalletCards} tone="green" label="Recebido líquido" value={money(received - refunded)} detail={`${money(refunded)} em estornos`} /><Metric icon={ReceiptText} tone="amber" label="Saldo em aberto" value={money(open.reduce((sum, entry) => sum + Number(entry.balance), 0))} detail={`${open.length} parcela(s)`} /><Metric icon={AlertCircle} tone="red" label="Em atraso" value={money(overdue.reduce((sum, entry) => sum + Number(entry.balance), 0))} detail={`${overdue.length} vencimento(s)`} /></section><div className="filter-chips"><button className={filter === "open" ? "active" : ""} onClick={() => setFilter("open")}>Em aberto</button><button className={filter === "overdue" ? "active" : ""} onClick={() => setFilter("overdue")}>Atrasadas</button><button className={filter === "paid" ? "active" : ""} onClick={() => setFilter("paid")}>Recebidas</button><button className={filter === "all" ? "active" : ""} onClick={() => setFilter("all")}>Todas</button></div><div className="receivable-table"><header><span>Cliente / ordem</span><span>Vencimento</span><span>Valor</span><span>Saldo</span><span>Status</span><span /></header>{visible.map((entry) => <article key={entry.id}><span><strong>{entry.order?.client?.name ?? "Cliente"}</strong><small>Ordem #{entry.order?.order_number} · Parcela {entry.installment_number}</small></span><span className={entry.due_date < today && entry.status !== "paid" ? "late" : ""}><strong>{shortDate(entry.due_date)}</strong><small>{entry.due_date < today && entry.status !== "paid" ? "Vencida" : ""}</small></span><span>{money(entry.amount)}</span><span><strong>{money(entry.balance)}</strong></span><span><i className={`finance-status ${entry.status}`}>{entry.status === "paid" ? "Recebida" : entry.status === "partial" ? "Parcial" : entry.status === "cancelled" ? "Cancelada" : "Pendente"}</i></span><span>{["pending", "partial"].includes(entry.status) && <button className="receive-button" onClick={() => onReceive(entry)}><CircleDollarSign /> Receber</button>}</span></article>)}</div>{!visible.length && <div className="panel"><Empty icon={CheckCircle2} title="Nenhuma conta neste filtro" text="Os próximos recebimentos aparecerão aqui." /></div>}</div>;
}

function ServicesView({ services, presets, isAdmin, onAddService, onEditService, onAddOption, onRefresh, notify }: { services: Service[]; presets: ReturnPreset[]; isAdmin: boolean; onAddService: () => void; onEditService: (service: Service) => void; onAddOption: (service: Service) => void; onRefresh: () => Promise<void>; notify: (text: string) => void }) {
  async function deleteService(service: Service) { if (!window.confirm(`Excluir o serviço “${service.name}” e seus modelos?`)) return; const { error } = await supabase.from("yan_services").delete().eq("id", service.id); if (error) notify(error.message); else await onRefresh(); }
  return <div><PageHeader kicker="Catálogo editável" title="Serviços, modelos e preços" text="Defina cálculo por modelo, unidade ou metro quadrado, além de custo, duração e prazo de retorno." action={<button className="button-admin-primary" onClick={onAddService}><Plus /> Novo serviço</button>} /><div className="service-admin-list">{services.map((service) => <section className="service-admin-card" key={service.id}><header><div className="catalog-icon"><Sparkles /></div><div><h2>{service.name}</h2><p>{service.description || "Sem descrição"}</p></div><span className={service.active ? "status-pill success" : "status-pill neutral"}>{service.active ? "Ativo" : "Pausado"}</span><button className="icon-button" onClick={() => onEditService(service)} title="Editar serviço"><Pencil /></button><button className="icon-button" onClick={() => onAddOption(service)} title="Adicionar modelo"><Plus /></button>{isAdmin && <button className="icon-button danger" onClick={() => void deleteService(service)} title="Excluir"><Trash2 /></button>}</header><div className="option-table"><div className="option-head"><span>Modelo</span><span>Cálculo</span><span>Venda</span><span>Custo</span><span>Duração</span><span>Retorno</span><span /></div>{service.options?.map((option) => <OptionRow key={option.id} option={option} presets={presets} isAdmin={isAdmin} onSaved={onRefresh} notify={notify} />)}{!service.options?.length && <div className="option-empty">Nenhum modelo cadastrado. <button onClick={() => onAddOption(service)}>Adicionar o primeiro</button></div>}</div></section>)}</div></div>;
}

function OptionRow({ option, presets, isAdmin, onSaved, notify }: { option: ServiceOption; presets: ReturnPreset[]; isAdmin: boolean; onSaved: () => Promise<void>; notify: (text: string) => void }) {
  const [editing, setEditing] = useState(false); const [form, setForm] = useState(option); const [busy, setBusy] = useState(false);
  async function save() { setBusy(true); const preset = presets.find((entry) => entry.id === form.return_preset_id); const { error } = await supabase.from("yan_service_options").update({ name: form.name, pricing_mode: form.pricing_mode, sale_price: form.sale_price, cost_price: form.cost_price, duration_minutes: form.duration_minutes, return_months: preset?.unit === "months" ? preset.value : form.return_months, return_preset_id: form.return_preset_id, active: form.active }).eq("id", option.id); if (error) notify(error.message); else { setEditing(false); await onSaved(); } setBusy(false); }
  async function toggle() { const { error } = await supabase.from("yan_service_options").update({ active: !option.active }).eq("id", option.id); if (error) notify(error.message); else await onSaved(); }
  async function remove() { if (!window.confirm(`Excluir o modelo “${option.name}”?`)) return; const { error } = await supabase.from("yan_service_options").delete().eq("id", option.id); if (error) notify(error.message); else await onSaved(); }
  if (editing) return <div className="option-edit"><input value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })} /><select value={form.pricing_mode} onChange={(e) => setForm({ ...form, pricing_mode: e.target.value as ServiceOption["pricing_mode"] })}><option value="fixed">Fechado</option><option value="per_unit">Unidade</option><option value="per_m2">m²</option></select><input type="number" min="0" step="0.01" value={form.sale_price ?? ""} onChange={(e) => setForm({ ...form, sale_price: e.target.value === "" ? null : Number(e.target.value) })} placeholder="Na ordem" /><input type="number" min="0" step="0.01" value={form.cost_price ?? ""} onChange={(e) => setForm({ ...form, cost_price: e.target.value === "" ? null : Number(e.target.value) })} placeholder="—" /><input type="number" min="5" value={form.duration_minutes} onChange={(e) => setForm({ ...form, duration_minutes: Number(e.target.value) })} /><select value={form.return_preset_id ?? ""} onChange={(e) => setForm({ ...form, return_preset_id: e.target.value || null })}>{presets.filter((preset) => preset.active).map((preset) => <option key={preset.id} value={preset.id}>{preset.label}</option>)}</select><span><button onClick={() => void save()} disabled={busy}>{busy ? <Loader2 className="spin" /> : <Save />}</button><button onClick={() => setEditing(false)}><X /></button></span></div>;
  const presetLabel = presets.find((preset) => preset.id === option.return_preset_id)?.label ?? `${option.return_months} meses`;
  return <div className={option.active ? "option-row" : "option-row inactive"}><span><strong>{option.name}</strong><small>{option.active ? "Disponível" : "Pausado"}</small></span><span>{option.pricing_mode === "fixed" ? "Fechado" : option.pricing_mode === "per_m2" ? "Por m²" : "Por unidade"}</span><span>{option.sale_price === null ? <strong className="price-on-demand">Na ordem</strong> : <strong>{money(option.sale_price)}</strong>}</span><span>{option.cost_price === null ? "—" : money(option.cost_price)}</span><span>{option.duration_minutes} min</span><span>{presetLabel}</span><span><button onClick={() => setEditing(true)} title="Editar"><Pencil /></button><button onClick={() => void toggle()} title={option.active ? "Pausar" : "Ativar"}>{option.active ? <Ban /> : <Check />}</button>{isAdmin && <button onClick={() => void remove()} title="Excluir"><Trash2 /></button>}</span></div>;
}

function SettingsView({ profile, profiles, settings, presets, onRefresh, notify }: { profile: Profile; profiles: Profile[]; settings: Settings | null; presets: ReturnPreset[]; onRefresh: () => Promise<void>; notify: (text: string) => void }) {
  const [form, setForm] = useState(settings); const [busy, setBusy] = useState(false);
  async function saveSettings(event: FormEvent) {
    event.preventDefault(); if (!form) return; setBusy(true);
    const { error } = await supabase.from("yan_settings").update({
      business_name: form.business_name,
      whatsapp: form.whatsapp.replace(/\D/g, ""),
      city: form.city,
      state: form.state.toUpperCase(),
      default_payment_days: form.default_payment_days,
      warranty_value: form.warranty_value,
      warranty_unit: form.warranty_unit,
      warranty_notes: form.warranty_notes.trim(),
    }).eq("id", "main");
    if (error) notify(error.message); else await onRefresh(); setBusy(false);
  }
  async function updateProfile(target: Profile, active: boolean, role: string) { const { error } = await supabase.rpc("yan_admin_set_profile", { p_user_id: target.user_id, p_active: active, p_role: role }); if (error) notify(error.message); else await onRefresh(); }
  return <div><PageHeader kicker="Administração" title="Configurações" text="Garantia do PDF, retornos, dados do negócio e acessos da equipe." />{profile.role !== "admin" ? <div className="panel"><Empty icon={ShieldCheck} title="Área do administrador" text="Somente administradores podem alterar estas configurações." /></div> : <div className="settings-grid">
    <section className="panel settings-card"><PanelHead icon={Settings2} title="Dados e garantia" subtitle="A garantia abaixo será impressa no PDF do cliente" />{form && <form className="modal-form settings-form" onSubmit={saveSettings}><div className="form-grid two"><label>Nome da empresa<input required value={form.business_name} onChange={(e) => setForm({ ...form, business_name: e.target.value })} /></label><label>WhatsApp<input required value={form.whatsapp} onChange={(e) => setForm({ ...form, whatsapp: e.target.value })} /></label><label>Cidade<input value={form.city} onChange={(e) => setForm({ ...form, city: e.target.value })} /></label><label>Estado<input maxLength={2} value={form.state} onChange={(e) => setForm({ ...form, state: e.target.value })} /></label><label>Prazo padrão para receber (dias)<input type="number" min="0" max="365" value={form.default_payment_days} onChange={(e) => setForm({ ...form, default_payment_days: Number(e.target.value) })} /></label></div><div className="warranty-settings"><div><ShieldCheck /><span><strong>Garantia no comprovante</strong><small>Este texto e prazo aparecem em todo PDF final.</small></span></div><div className="form-grid two"><label>Prazo da garantia<input type="number" min="1" max="3650" value={form.warranty_value} onChange={(e) => setForm({ ...form, warranty_value: Number(e.target.value) })} /></label><label>Unidade<select value={form.warranty_unit} onChange={(e) => setForm({ ...form, warranty_unit: e.target.value as YanSettings["warranty_unit"] })}><option value="days">Dias</option><option value="months">Meses</option></select></label></div><label>Condições da garantia<textarea rows={4} value={form.warranty_notes} onChange={(e) => setForm({ ...form, warranty_notes: e.target.value })} placeholder="Explique o que a garantia cobre." /></label></div><button className="button-admin-primary" disabled={busy}>{busy ? <Loader2 className="spin" /> : <Save />}Salvar dados e garantia</button></form>}</section>
    <section className="panel settings-card return-settings-card"><PanelHead icon={CalendarClock} title="Prazos de retorno" subtitle="Crie, edite, pause ou exclua os alertas disponíveis" /><ReturnPresetsManager presets={presets} onRefresh={onRefresh} notify={notify} /></section>
    <section className="panel settings-card team-settings-card"><PanelHead icon={UsersRound} title="Equipe" subtitle="Aprove novos acessos e defina administradores" /><div className="team-list">{profiles.map((member) => <article key={member.user_id}><div>{(member.full_name ?? member.email).slice(0, 1).toUpperCase()}</div><span><strong>{member.full_name || "Sem nome"}</strong><small>{member.email}</small></span><select value={member.role} onChange={(e) => void updateProfile(member, member.active, e.target.value)} disabled={member.user_id === profile.user_id}><option value="agent">Atendente</option><option value="admin">Administrador</option></select><button className={member.active ? "team-active" : "team-pending"} onClick={() => void updateProfile(member, !member.active, member.role)} disabled={member.user_id === profile.user_id}>{member.active ? <><Check /> Ativo</> : "Aprovar"}</button></article>)}</div></section>
  </div>}</div>;
}

function ReturnPresetsManager({ presets, onRefresh, notify }: { presets: ReturnPreset[]; onRefresh: () => Promise<void>; notify: (text: string) => void }) {
  const [value, setValue] = useState(1); const [unit, setUnit] = useState<ReturnPreset["unit"]>("months"); const [label, setLabel] = useState(""); const [busy, setBusy] = useState(false);
  async function create(event: FormEvent) {
    event.preventDefault(); setBusy(true);
    const generatedLabel = label.trim() || `${value} ${unit === "days" ? value === 1 ? "dia" : "dias" : value === 1 ? "mês" : "meses"}`;
    const { error } = await supabase.from("yan_return_presets").insert({ label: generatedLabel, value, unit, sort_order: Math.max(0, ...presets.map((entry) => entry.sort_order)) + 10 });
    if (error) notify(error.code === "23505" ? "Esse prazo já existe. Edite o prazo existente." : error.message); else { setLabel(""); await onRefresh(); }
    setBusy(false);
  }
  return <div className="return-preset-manager"><form className="return-preset-create" onSubmit={create}><label>Quantidade<input type="number" min="1" max="3650" value={value} onChange={(event) => setValue(Number(event.target.value))} /></label><label>Período<select value={unit} onChange={(event) => setUnit(event.target.value as ReturnPreset["unit"])}><option value="days">Dia(s)</option><option value="months">Mês(es)</option></select></label><label>Nome exibido <span>opcional</span><input value={label} onChange={(event) => setLabel(event.target.value)} placeholder="Ex.: Retorno em 3 meses" /></label><button className="button-admin-primary" disabled={busy}>{busy ? <Loader2 className="spin" /> : <Plus />}Criar prazo</button></form><div className="return-preset-list">{presets.map((preset) => <ReturnPresetRow key={preset.id} preset={preset} onRefresh={onRefresh} notify={notify} />)}</div></div>;
}

function ReturnPresetRow({ preset, onRefresh, notify }: { preset: ReturnPreset; onRefresh: () => Promise<void>; notify: (text: string) => void }) {
  const [editing, setEditing] = useState(false); const [label, setLabel] = useState(preset.label); const [value, setValue] = useState(preset.value); const [unit, setUnit] = useState<ReturnPreset["unit"]>(preset.unit); const [busy, setBusy] = useState(false);
  async function save() { setBusy(true); const { error } = await supabase.from("yan_return_presets").update({ label: label.trim(), value, unit }).eq("id", preset.id); if (error) notify(error.code === "23505" ? "Esse prazo já existe." : error.message); else { setEditing(false); await onRefresh(); } setBusy(false); }
  async function toggle() { setBusy(true); const { error } = await supabase.from("yan_return_presets").update({ active: !preset.active }).eq("id", preset.id); if (error) notify(error.message); else await onRefresh(); setBusy(false); }
  async function remove() { if (!window.confirm(`Excluir o prazo “${preset.label}”?`)) return; setBusy(true); const { error } = await supabase.from("yan_return_presets").delete().eq("id", preset.id); if (error) notify(error.message); else await onRefresh(); setBusy(false); }
  if (editing) return <article className="return-preset-row editing"><input value={label} onChange={(event) => setLabel(event.target.value)} aria-label="Nome do prazo" /><input type="number" min="1" max="3650" value={value} onChange={(event) => setValue(Number(event.target.value))} aria-label="Quantidade" /><select value={unit} onChange={(event) => setUnit(event.target.value as ReturnPreset["unit"])} aria-label="Unidade"><option value="days">Dias</option><option value="months">Meses</option></select><span><button onClick={() => void save()} disabled={busy} title="Salvar"><Save /></button><button onClick={() => setEditing(false)} title="Cancelar"><X /></button></span></article>;
  return <article className={preset.active ? "return-preset-row" : "return-preset-row inactive"}><span className="return-preset-icon"><CalendarClock /></span><span><strong>{preset.label}</strong><small>{preset.value} {preset.unit === "days" ? preset.value === 1 ? "dia" : "dias" : preset.value === 1 ? "mês" : "meses"} · {preset.active ? "Disponível" : "Pausado"}</small></span><span className="return-preset-actions"><button onClick={() => setEditing(true)} disabled={busy} title="Editar"><Pencil /></button><button onClick={() => void toggle()} disabled={busy} title={preset.active ? "Pausar" : "Ativar"}>{preset.active ? <Ban /> : <Check />}</button><button onClick={() => void remove()} disabled={busy} title="Excluir"><Trash2 /></button></span></article>;
}

function PageHeader({ kicker, title, text, action }: { kicker: string; title: string; text: string; action?: React.ReactNode }) { return <header className="page-header"><div><span className="page-kicker">{kicker}</span><h1>{title}</h1><p>{text}</p></div>{action}</header>; }
function statusName(status: Order["status"]) { return { draft: "Orçamento", scheduled: "Agendada", in_progress: "Em andamento", completed: "Concluída", cancelled: "Cancelada", refunded: "Estornada" }[status]; }
